import { randomUUID } from 'node:crypto';
import { tx, closeDatabase } from '../src/db.js';
import { encryptSecret, generateTotpSecret, hashPassword } from '../src/security.js';
const username=String(process.env.ADMIN_USERNAME||'').trim();const password=String(process.env.ADMIN_PASSWORD||'');const roles=String(process.env.ADMIN_ROLES||'SUPERVISOR').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);if(!/^[a-zA-Z0-9_.-]{3,30}$/.test(username))throw new Error('ADMIN_USERNAME is required');if(password.length<14)throw new Error('ADMIN_PASSWORD must contain at least 14 characters');const allowed=new Set(['SUPERVISOR','FINANCE','RESULT_OPERATOR','SUPPORT','SECURITY']);if(!roles.length||roles.some(x=>!allowed.has(x)))throw new Error('ADMIN_ROLES contains an unsupported role');const secret=String(process.env.ADMIN_TOTP_SECRET||generateTotpSecret()).replace(/\s/g,'');const passwordHash=await hashPassword(password);const encrypted=encryptSecret(secret);let userId;
await tx(async client=>{const existing=await client.query('SELECT id FROM users WHERE username=$1',[username]);userId=existing.rows[0]?.id||randomUUID();if(existing.rowCount)await client.query(`UPDATE users SET password_hash=$1,mfa_enabled=true,mfa_secret_encrypted=$2,status='ACTIVE',updated_at=now() WHERE id=$3`,[passwordHash,encrypted,userId]);else await client.query(`INSERT INTO users(id,username,password_hash,status,mfa_enabled,mfa_secret_encrypted,rules_accepted_at) VALUES($1,$2,$3,'ACTIVE',true,$4,now())`,[userId,username,passwordHash,encrypted]);for(const role of roles)await client.query(`INSERT INTO user_roles(user_id,role_code,assigned_by) VALUES($1,$2,$1) ON CONFLICT DO NOTHING`,[userId,role]);});
const issuer=encodeURIComponent('ASEAN777 Admin');const label=encodeURIComponent(`ASEAN777:${username}`);console.log(JSON.stringify({username,userId,roles,totpSecret:secret,otpauthUri:`otpauth://totp/${label}?secret=${secret}&issuer=${issuer}&algorithm=SHA1&digits=6&period=30`},null,2));await closeDatabase();
